failed = 0

def check(ok: bool, msg: str):
    global failed
    if not ok:
        print("FAIL", msg)
        failed += 1

def close(got, exp: List[float], rtol: float = 1e-8, atol: float = 1e-10) -> bool:
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    for i in range(len(exp)):
        if abs(g[i] - exp[i]) > atol + rtol * abs(exp[i]):
            print("mismatch at", i, g[i], exp[i])
            return False
    return True

from sklearn.svm import LinearSVC

def data(n: int, p: int, nc: int):
    X = np.zeros((n, p))
    y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * float(y[i]) if (j + y[i]) % 2 == 0 else -0.3 * float(y[i]))
    return X, y

